/* The Stack Overflow Cliff — all charts are hand-drawn SVG, no libraries. */
/* Data comes from data/so_counts.js (window.SO_DATA), generated by scripts/fetch_data.py */
const DATA = window.SO_DATA;

/* ---------- helpers ---------- */
const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const fmt = n => Math.round(n).toLocaleString("en-GB");
const fmtK = n => n >= 1e6 ? (n / 1e6).toFixed(2).replace(/0$/, "") + "M" : n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 0 : 1).replace(/\.0$/, "") + "k" : String(Math.round(n));
const pct = (x, d = 0) => (x > 0 ? "+" : x < 0 ? "−" : "") + Math.abs(x).toFixed(d) + "%";
const share = x => (x < 10 ? x.toFixed(1) : Math.round(x)) + "%";
const mLabel = k => MONTHS[+k.slice(5) - 1] + " " + k.slice(0, 4);
const qLabel = k => k.replace("-", " ");
const avg = a => a.reduce((s, x) => s + x, 0) / a.length;
const NS = "http://www.w3.org/2000/svg";
function el(tag, attrs = {}, parent) { const e = document.createElementNS(NS, tag); for (const [k, v] of Object.entries(attrs)) if (v !== null && v !== undefined) e.setAttribute(k, v); if (parent) parent.appendChild(e); return e; }
function txt(parent, attrs, s) { const t = el("text", attrs, parent); t.textContent = s; return t; }
function frame(host, H, m, label) {
  host.querySelectorAll("svg, .tip").forEach(n => n.remove());
  const W = Math.max(120, host.clientWidth);
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H, role: "img", "aria-label": label }, host);
  return { svg, W, H, m, iw: W - m.l - m.r, ih: H - m.t - m.b };
}
function makeTip(host) { const t = document.createElement("div"); t.className = "tip"; t.hidden = true; host.appendChild(t); return t; }
function showTip(tip, host, html, px, py) {
  tip.innerHTML = html; tip.hidden = false;
  const w = host.clientWidth, tw = tip.offsetWidth;
  tip.style.left = Math.max(tw / 2, Math.min(w - tw / 2, px)) + "px";
  tip.style.top = Math.max(tip.offsetHeight + 10, py) + "px";
}
function hover(svg, f, x0, w, onMove, onLeave) {
  const hit = el("rect", { x: x0, y: 0, width: w, height: f.H, fill: "transparent" }, svg);
  const mv = ev => { const r = svg.getBoundingClientRect(); onMove((ev.clientX - r.left) * (f.W / r.width), (ev.clientY - r.top) * (f.H / r.height), r); };
  hit.addEventListener("pointermove", mv); hit.addEventListener("pointerdown", mv); hit.addEventListener("pointerleave", onLeave);
  return hit;
}

/* ---------- derived data (everything shown is computed here) ---------- */
if (DATA.pulled) {
  const d = new Date(DATA.pulled + "T12:00:00Z");
  document.querySelectorAll("[data-pulled]").forEach(e => (e.textContent = d.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" })));
  document.querySelectorAll("[data-pulled-short]").forEach(e => (e.textContent = d.toLocaleDateString("en-GB", { month: "short", year: "numeric" })));
}
const months = Object.keys(DATA.site).sort();
const site = months.map(k => ({ k, v: DATA.site[k] }));
const peak = site.reduce((a, b) => (b.v > a.v ? b : a));
const last = site[site.length - 1];
const launchK = "2022-11", launch = DATA.site[launchK];
const firstY = +months[0].slice(0, 4), lastY = +last.k.slice(0, 4);
const years = []; for (let y = firstY; y <= lastY; y++) years.push(y);
const yearTot = years.map(y => ({ y, v: site.filter(d => +d.k.slice(0, 4) === y).reduce((s, d) => s + d.v, 0), n: site.filter(d => +d.k.slice(0, 4) === y).length }));
const sum2025 = (yearTot.find(d => d.y === 2025) || {}).v;
const yoyM = site.map(d => { const p = DATA.site[`${+d.k.slice(0, 4) - 1}${d.k.slice(4)}`]; return p ? { k: d.k, v: (d.v / p - 1) * 100 } : null; }).filter(Boolean);
const lastYoY = yoyM[yoyM.length - 1];
const quarters = Object.keys(DATA.tags.python).sort();
const siteQ = {};
for (const d of site) { const q = `${d.k.slice(0, 4)}-Q${Math.ceil(+d.k.slice(5) / 3)}`; siteQ[q] = (siteQ[q] || 0) + d.v; }
const TAGS = ["python", "pandas", "sql", "excel", "powerbi"];
function profile(series) {
  const base = avg(quarters.filter(k => k.startsWith("2021")).map(k => series[k]));
  const recent = avg(quarters.slice(-4).map(k => series[k]));
  const below = f => quarters.find(k => k > "2022" && series[k] < base * f);
  return { base, recent, left: (recent / base) * 100, b50: below(0.5), b25: below(0.25), b10: below(0.1),
    idx: quarters.map(k => ({ k, v: series[k], i: (series[k] / base) * 100 })) };
}
const P = {}; TAGS.forEach(t => (P[t] = profile(DATA.tags[t]))); P.site = profile(siteQ);
const siteBase = P.site.base;
const shareIdx = {};
TAGS.forEach(t => { const b = P[t].base / siteBase; shareIdx[t] = quarters.map(q => ({ k: q, s: DATA.tags[t][q] / siteQ[q] * 100, i: (DATA.tags[t][q] / siteQ[q]) / b * 100 })); });
const color = t => t === "site" ? "var(--line)" : `var(--t-${t})`;
const label = t => t === "site" ? "All questions" : t;
let focus = null;
const isOff = t => focus && focus !== t;

/* ---------- KPI tiles ---------- */
function sparkLine(host, vals, opt = {}) {
  const f = frame(host, 40, { t: 4, r: 6, b: 4, l: 2 }, opt.label || "trend");
  const mx = Math.max(...vals), mn = opt.zero ? 0 : Math.min(...vals);
  const x = i => f.m.l + (i / (vals.length - 1)) * f.iw, y = v => f.m.t + f.ih - ((v - mn) / (mx - mn || 1)) * f.ih;
  const d = "M" + vals.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join("L");
  el("path", { d: `${d}L${x(vals.length - 1)},${f.m.t + f.ih}L${x(0)},${f.m.t + f.ih}Z`, fill: "var(--fill)" }, f.svg);
  el("path", { d, fill: "none", stroke: opt.stroke || "var(--line)", "stroke-width": 1.75, "stroke-linejoin": "round" }, f.svg);
  const hi = opt.mark ?? vals.length - 1;
  el("circle", { cx: x(hi), cy: y(vals[hi]), r: 3.5, fill: opt.dot || "var(--ai)", stroke: "var(--card)", "stroke-width": 1.5 }, f.svg);
}
function sparkBars(host, vals, hiFrom) {
  const f = frame(host, 40, { t: 4, r: 2, b: 2, l: 2 }, "yearly totals");
  const mx = Math.max(...vals), bw = f.iw / vals.length;
  vals.forEach((v, i) => el("rect", { x: f.m.l + i * bw + 1, y: f.m.t + f.ih - (v / mx) * f.ih, width: Math.max(1, bw - 2), height: Math.max(1, (v / mx) * f.ih), rx: 1.5, fill: i >= hiFrom ? "var(--ai)" : "var(--dim)" }, f.svg));
}
function drawKpis() {
  const fullYears = yearTot.filter(d => d.n === 12);
  const tiles = [
    { label: `New questions, ${mLabel(last.k)}`, value: fmt(last.v), ai: true, delta: `<b>${pct(lastYoY.v)}</b> vs ${mLabel(lastYoY.k.replace(/^\d{4}/, String(+lastYoY.k.slice(0, 4) - 1)))}`,
      spark: h => sparkLine(h, site.slice(-24).map(d => d.v), { zero: true }) },
    { label: `Peak month, ${mLabel(peak.k)}`, value: fmt(peak.v), delta: `<b>${pct((last.v / peak.v - 1) * 100, 1)}</b> peak to latest`,
      spark: h => sparkLine(h, site.map(d => d.v), { zero: true, mark: site.indexOf(peak), dot: "var(--line)" }) },
    { label: "Since ChatGPT launched", value: pct((last.v / launch - 1) * 100), ai: true, delta: `${fmt(launch)} in ${mLabel(launchK)} → ${fmt(last.v)}`,
      spark: h => sparkLine(h, site.slice(months.indexOf(launchK)).map(d => d.v), { zero: true }) },
    { label: "Questions in 2025", value: fmtK(sum2025), delta: sum2025 < peak.v ? `Less than ${mLabel(peak.k)} alone` : "Full year",
      spark: h => sparkBars(h, fullYears.map(d => d.v), fullYears.findIndex(d => d.y >= 2023)) },
  ];
  const box = document.getElementById("kpis"); box.innerHTML = "";
  tiles.forEach(t => {
    const a = document.createElement("article"); a.className = "tile kpi s3";
    a.innerHTML = `<span class="label">${t.label}</span><span class="value${t.ai ? " ai" : ""}">${t.value}</span><span class="delta">${t.delta}</span><div class="chart spark"></div>`;
    box.appendChild(a); t.spark(a.querySelector(".spark"));
  });
}

/* ---------- cliff (dashboard + LinkedIn card) ---------- */
let logScale = false, animated = false;
function cliffSVG(host, opt) {
  const W = opt.W, H = opt.H, k = opt.scale || 1, small = !opt.card && W < 520, fs = n => n * k;
  const m = { t: fs(26), r: small ? 12 : fs(48), b: fs(26), l: fs(42) };
  const iw = W - m.l - m.r, ih = H - m.t - m.b, C = opt.colors, font = "Instrument Sans, system-ui, sans-serif";
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": `Monthly new questions, ${fmt(peak.v)} at the ${mLabel(peak.k)} peak, ${fmt(last.v)} in ${mLabel(last.k)}` }, host);
  if (!opt.card) { svg.setAttribute("width", W); svg.setAttribute("height", H); }
  const linMax = Math.ceil(peak.v / 50000) * 50000, lo = 500, hi = 300000, useLog = !opt.card && logScale;
  const x = i => m.l + (i / (site.length - 1)) * iw;
  const y = v => useLog ? m.t + ih - ((Math.log10(Math.max(v, lo)) - Math.log10(lo)) / (Math.log10(hi) - Math.log10(lo))) * ih : m.t + ih - (v / linMax) * ih;
  const idx = kk => months.indexOf(kk), yB = m.t + ih, xe = x(idx(launchK) + 29 / 30);
  el("rect", { x: xe, y: m.t, width: m.l + iw - xe, height: ih, fill: C.wash }, svg);
  const ticks = useLog ? [500, 1000, 3000, 10000, 30000, 100000, 300000] : Array.from({ length: linMax / 50000 + 1 }, (_, i) => i * 50000);
  ticks.forEach((v, i) => {
    el("line", { x1: m.l, x2: m.l + iw, y1: y(v), y2: y(v), stroke: i === 0 ? C.axis : C.grid, "stroke-width": k }, svg);
    txt(svg, { x: m.l - fs(7), y: y(v) + fs(4), "text-anchor": "end", fill: C.muted, "font-size": fs(11), "font-family": font }, v === 0 ? "0" : fmtK(v));
  });
  years.forEach(yr => {
    const i = idx(`${yr}-01`); if (i < 0) return;
    el("line", { x1: x(i), x2: x(i), y1: yB, y2: yB + fs(4), stroke: C.axis, "stroke-width": k }, svg);
    if (small && yr % 2) return;
    txt(svg, { x: x(i), y: H - fs(7), fill: C.muted, "font-size": fs(11), "font-family": font }, small ? "’" + String(yr).slice(2) : String(yr));
  });
  const d = "M" + site.map((p, i) => x(i).toFixed(1) + "," + y(p.v).toFixed(1)).join("L");
  el("path", { d: `${d}L${x(site.length - 1).toFixed(1)},${yB}L${x(0)},${yB}Z`, fill: C.fill }, svg);
  const path = el("path", { d, fill: "none", stroke: C.line, "stroke-width": 2 * k, "stroke-linejoin": "round", "stroke-linecap": "round" }, svg);
  if (opt.animate) { try { path.style.setProperty("--len", path.getTotalLength()); path.classList.add("draw"); } catch (e) {} }
  el("line", { x1: xe, x2: xe, y1: m.t - fs(8), y2: yB, stroke: C.ai, "stroke-width": 1.5 * k, "stroke-dasharray": `${4 * k} ${3 * k}` }, svg);
  txt(svg, { x: xe + fs(7), y: m.t + (small ? 18 : fs(4)), fill: C.ai, "font-size": fs(11.5), "font-weight": 600, "font-family": font }, opt.card ? "ChatGPT launches · 30 Nov 2022" : "ChatGPT");
  const pi = idx(peak.k);
  el("circle", { cx: x(pi), cy: y(peak.v), r: 3.5 * k, fill: C.bg, stroke: C.line, "stroke-width": 2 * k }, svg);
  txt(svg, { x: x(pi) + fs(8), y: y(peak.v) - fs(7), fill: C.ink, "font-size": fs(11.5), "font-weight": 600, "font-family": font }, opt.card ? `${fmt(peak.v)} · ${mLabel(peak.k)}` : `${fmtK(peak.v)} peak`);
  const li = site.length - 1;
  el("circle", { cx: x(li), cy: y(last.v), r: 5 * k, fill: C.ai, stroke: C.bg, "stroke-width": 2 * k }, svg);
  txt(svg, small ? { x: x(li) - 3, y: y(last.v) - 10, "text-anchor": "end", fill: C.ai, "font-size": 12, "font-weight": 700, "font-family": font }
                 : { x: x(li) + fs(9), y: y(last.v) + fs(4), fill: C.ai, "font-size": fs(12.5), "font-weight": 700, "font-family": font }, fmt(last.v));
  if (opt.card) return;
  const tip = makeTip(host);
  const cross = el("line", { y1: m.t, y2: yB, stroke: C.muted, "stroke-width": 1, visibility: "hidden" }, svg);
  const dot = el("circle", { r: 4, fill: C.line, stroke: C.bg, "stroke-width": 2, visibility: "hidden" }, svg);
  hover(svg, { W, H }, m.l, iw, (sx, sy, r) => {
    const i = Math.max(0, Math.min(li, Math.round(((sx - m.l) / iw) * li))), p = site[i];
    cross.setAttribute("x1", x(i)); cross.setAttribute("x2", x(i)); cross.setAttribute("visibility", "visible");
    dot.setAttribute("cx", x(i)); dot.setAttribute("cy", y(p.v)); dot.setAttribute("visibility", "visible");
    const yy = yoyM.find(q => q.k === p.k);
    showTip(tip, host, `<div class="t">${mLabel(p.k)}</div><div class="row">Questions<b>${fmt(p.v)}</b></div>` + (yy ? `<div class="row">vs a year earlier<b>${pct(yy.v)}</b></div>` : ""), x(i) / W * r.width, y(p.v) / H * r.height);
  }, () => { tip.hidden = true; cross.setAttribute("visibility", "hidden"); dot.setAttribute("visibility", "hidden"); });
}
const themeC = { wash: "var(--ai-wash)", grid: "var(--rule)", axis: "var(--axis)", muted: "var(--muted)", fill: "var(--fill)", line: "var(--line)", ai: "var(--ai)", bg: "var(--card)", ink: "var(--ink)" };
function drawCliff() {
  const host = document.getElementById("cliff"); host.querySelectorAll("svg, .tip").forEach(n => n.remove());
  const W = Math.max(280, host.clientWidth);
  cliffSVG(host, { W, H: W < 520 ? 250 : 300, colors: themeC, animate: !animated }); animated = true;
}
function setScale(log) {
  logScale = log;
  document.getElementById("scale-lin").setAttribute("aria-pressed", String(!log));
  document.getElementById("scale-log").setAttribute("aria-pressed", String(log));
  drawCliff();
}

/* ---------- annual bars ---------- */
function drawAnnual() {
  const host = document.getElementById("annual");
  const f = frame(host, 300, { t: 22, r: 4, b: 24, l: 4 }, "Questions per year");
  const mx = Math.max(...yearTot.map(d => d.v)) * 1.05, n = yearTot.length, bw = f.iw / n;
  const y = v => f.m.t + f.ih - (v / mx) * f.ih;
  el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: y(0), y2: y(0), class: "base" }, f.svg);
  const tip = makeTip(host);
  yearTot.forEach((d, i) => {
    const partial = d.n < 12, post = d.y >= 2023;
    const x0 = f.m.l + i * bw + bw * 0.14, w = bw * 0.72;
    el("rect", { x: x0, y: y(d.v), width: w, height: Math.max(1, y(0) - y(d.v)), rx: 3, fill: post ? "var(--ai)" : "var(--line)", opacity: partial ? 0.45 : post ? 0.9 : 0.85 }, f.svg);
    let ly = y(d.v) - 5; if (Math.abs(ly - 4 - y(peak.v)) < 10) ly = y(peak.v) - 4;
    txt(f.svg, { x: x0 + w / 2, y: ly, "text-anchor": "middle", class: "lbl", "font-size": 11 }, fmtK(d.v));
    txt(f.svg, { x: x0 + w / 2, y: f.H - 7, "text-anchor": "middle", class: "tick" }, partial ? `’${String(d.y).slice(2)}*` : `’${String(d.y).slice(2)}`);
    const hit = el("rect", { x: f.m.l + i * bw, y: 0, width: bw, height: f.H, fill: "transparent" }, f.svg);
    const sh = () => { const r = f.svg.getBoundingClientRect(); showTip(tip, host, `<div class="t">${d.y}${partial ? ` (Jan–${MONTHS[d.n - 1]})` : ""}</div><div class="row">Questions<b>${fmt(d.v)}</b></div>`, (x0 + w / 2) / f.W * r.width, y(d.v) / f.H * r.height); };
    hit.addEventListener("pointerenter", sh); hit.addEventListener("pointerdown", sh); hit.addEventListener("pointerleave", () => (tip.hidden = true));
  });
  const yp = y(peak.v);
  el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: yp, y2: yp, stroke: "var(--ai)", "stroke-width": 1.2, "stroke-dasharray": "4 3" }, f.svg);
  const pIdx = yearTot.findIndex(d => d.n < 12);
  if (pIdx >= 0) txt(f.svg, { x: f.m.l, y: 10, class: "tick" }, `* ${yearTot[pIdx].y}: Jan–${MONTHS[yearTot[pIdx].n - 1]}`);
}

/* ---------- YoY bars ---------- */
function drawYoY() {
  const host = document.getElementById("yoy");
  const f = frame(host, 230, { t: 14, r: 34, b: 22, l: 38 }, "Year-on-year change by month");
  const lo = -100, hi = Math.ceil(Math.max(...yoyM.map(d => d.v)) / 25) * 25;
  const y = v => f.m.t + ((hi - v) / (hi - lo)) * f.ih, n = yoyM.length, bw = f.iw / n;
  for (let v = lo; v <= hi; v += 25) {
    el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: y(v), y2: y(v), class: v === 0 ? "base" : "grid" }, f.svg);
    txt(f.svg, { x: f.m.l - 6, y: y(v) + 4, "text-anchor": "end", class: "tick" }, (v > 0 ? "+" : "") + v + "%");
  }
  yoyM.forEach((d, i) => el("rect", { x: f.m.l + i * bw + 0.5, y: Math.min(y(0), y(d.v)), width: Math.max(1, bw - 1), height: Math.max(1, Math.abs(y(d.v) - y(0))), fill: d.v < 0 && d.k > launchK ? "var(--ai)" : d.v < 0 ? "var(--pos)" : "var(--dim)" }, f.svg));
  const li = yoyM.findIndex(d => d.k === launchK);
  if (li >= 0) { const xl = f.m.l + (li + 1) * bw; el("line", { x1: xl, x2: xl, y1: f.m.t, y2: f.m.t + f.ih, stroke: "var(--ai)", "stroke-dasharray": "4 3", "stroke-width": 1.2 }, f.svg); txt(f.svg, { x: xl - 5, y: y(hi) + 10, "text-anchor": "end", class: "ann" }, "ChatGPT"); }
  years.forEach(yr => { const i = yoyM.findIndex(d => d.k === `${yr}-01`); if (i >= 0 && (f.W > 520 || yr % 2 === 1)) txt(f.svg, { x: f.m.l + i * bw, y: f.H - 6, class: "tick" }, f.W > 520 ? String(yr) : "’" + String(yr).slice(2)); });
  const L = yoyM[n - 1];
  txt(f.svg, { x: f.m.l + f.iw + 4, y: y(L.v) + 4, class: "ann" }, pct(L.v));
  const tip = makeTip(host);
  hover(f.svg, f, f.m.l, f.iw, (sx, sy, r) => {
    const i = Math.max(0, Math.min(n - 1, Math.floor((sx - f.m.l) / bw))), d = yoyM[i];
    showTip(tip, host, `<div class="t">${mLabel(d.k)} vs ${MONTHS[+d.k.slice(5) - 1]} ${+d.k.slice(0, 4) - 1}</div><div class="row">Change<b>${pct(d.v, 1)}</b></div>`, (f.m.l + (i + 0.5) * bw) / f.W * r.width, y(Math.max(0, d.v)) / f.H * r.height);
  }, () => (tip.hidden = true));
}

/* ---------- heatmap ---------- */
const HEAT_EDGES = [2000, 5000, 15000, 40000, 80000, 120000];
const heatStep = v => 1 + HEAT_EDGES.filter(e => v >= e).length;
const heatColor = v => `var(--h${heatStep(v)})`;
function drawHeat() {
  const host = document.getElementById("heat");
  const small = host.clientWidth < 520;
  const rowH = small ? 20 : 23, m = { t: 18, r: 2, b: 30, l: 40 };
  const f = frame(host, m.t + years.length * rowH + m.b, m, "Monthly questions heatmap");
  const cw = f.iw / 12;
  MONTHS.forEach((mo, j) => txt(f.svg, { x: f.m.l + j * cw + cw / 2, y: 12, "text-anchor": "middle", class: "tick" }, small ? mo[0] : mo));
  const tip = makeTip(host);
  years.forEach((yr, i) => {
    const yy = f.m.t + i * rowH;
    txt(f.svg, { x: f.m.l - 7, y: yy + rowH / 2 + 4, "text-anchor": "end", class: "tick" }, String(yr));
    MONTHS.forEach((mo, j) => {
      const k = `${yr}-${String(j + 1).padStart(2, "0")}`, v = DATA.site[k];
      const x0 = f.m.l + j * cw;
      if (v === undefined) { el("rect", { x: x0 + 1, y: yy + 1, width: cw - 2, height: rowH - 2, rx: 2, fill: "none", stroke: "var(--rule)" }, f.svg); return; }
      const c = el("rect", { x: x0 + 1, y: yy + 1, width: cw - 2, height: rowH - 2, rx: 2, fill: heatColor(v) }, f.svg);
      if (k === peak.k || k === launchK) el("rect", { x: x0 + 1, y: yy + 1, width: cw - 2, height: rowH - 2, rx: 2, fill: "none", stroke: k === launchK ? "var(--ai)" : "var(--ink)", "stroke-width": 2 }, f.svg);
      if (!small && cw > 34) {
        const tIdx = heatStep(v);
        txt(f.svg, { x: x0 + cw / 2, y: yy + rowH / 2 + 4, "text-anchor": "middle", "font-size": 10, "font-family": "Instrument Sans, system-ui, sans-serif", fill: tIdx >= 4 ? "var(--ht-hi)" : "var(--ht-lo)", "pointer-events": "none" }, fmtK(v));
      }
      const sh = () => { const r = f.svg.getBoundingClientRect(); showTip(tip, host, `<div class="t">${mLabel(k)}${k === launchK ? " · ChatGPT launch" : k === peak.k ? " · peak" : ""}</div><div class="row">Questions<b>${fmt(v)}</b></div>`, (x0 + cw / 2) / f.W * r.width, yy / f.H * r.height); };
      c.addEventListener("pointerenter", sh); c.addEventListener("pointerdown", sh); c.addEventListener("pointerleave", () => (tip.hidden = true));
    });
  });
  // scale legend
  const ly = f.m.t + years.length * rowH + 10, lw = Math.min(280, f.iw * 0.62), sw = lw / 7;
  for (let s = 1; s <= 7; s++) el("rect", { x: f.m.l + (s - 1) * sw, y: ly, width: sw - 1, height: 8, fill: `var(--h${s})` }, f.svg);
  HEAT_EDGES.forEach((e, i) => { if (!small || i % 2 === 1) txt(f.svg, { x: f.m.l + (i + 1) * sw, y: ly + 20, "text-anchor": "middle", class: "tick", "font-size": 10 }, fmtK(e)); });
  if (f.iw - lw > 110) { el("rect", { x: f.m.l + lw + 16, y: ly, width: 10, height: 8, fill: "none", stroke: "var(--ai)", "stroke-width": 2 }, f.svg);
    txt(f.svg, { x: f.m.l + lw + 30, y: ly + 8, class: "tick" }, "ChatGPT launch"); }
}

/* ---------- tag chips ---------- */
function drawChips() {
  const box = document.getElementById("chips"); box.innerHTML = "";
  TAGS.forEach(t => {
    const b = document.createElement("button"); b.type = "button"; b.className = "chip"; b.id = "chip-" + t;
    b.style.setProperty("--c", color(t)); b.setAttribute("aria-pressed", String(focus === t));
    b.innerHTML = `<i></i>${t}`;
    b.addEventListener("click", () => { focus = focus === t ? null : t; drawTagCharts(); document.getElementById("chip-" + t).focus(); });
    box.appendChild(b);
  });
  if (focus) { const r = document.createElement("button"); r.type = "button"; r.className = "chip reset"; r.id = "chip-reset"; r.textContent = "Show all"; r.addEventListener("click", () => { focus = null; drawTagCharts(); }); box.appendChild(r); }
}

/* ---------- small multiples ---------- */
const order = [...TAGS, "site"].sort((a, b) => P[a].left - P[b].left);
const yMaxIdx = Math.ceil(Math.max(...order.flatMap(t => P[t].idx.map(d => d.i))) / 25) * 25;
function drawMultis() {
  const box = document.getElementById("multis"); box.innerHTML = "";
  order.forEach(t => {
    const p = P[t], card = document.createElement("div");
    card.className = "multi" + (t !== "site" && isOff(t) ? " off" : "");
    card.style.setProperty("--c", color(t));
    card.innerHTML = `<div class="multi-top"><span class="name"><i></i>${label(t)}</span><span class="v">${share(p.left)}</span></div><div class="chart"></div><span class="h">&lt;50% since ${qLabel(p.b50)}</span>`;
    box.appendChild(card);
    const host = card.querySelector(".chart");
    const f = frame(host, 84, { t: 6, r: 4, b: 14, l: 22 }, `${label(t)}: ${share(p.left)} of 2021 volume left`);
    const x = i => f.m.l + (i / (quarters.length - 1)) * f.iw, y = v => f.m.t + f.ih - (v / yMaxIdx) * f.ih;
    const qe = quarters.indexOf("2022-Q4");
    el("rect", { x: x(qe), y: f.m.t, width: f.m.l + f.iw - x(qe), height: f.ih, fill: "var(--ai-wash)" }, f.svg);
    el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: y(100), y2: y(100), stroke: "var(--axis)", "stroke-dasharray": "3 3" }, f.svg);
    el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: y(0), y2: y(0), class: "base" }, f.svg);
    txt(f.svg, { x: f.m.l - 4, y: y(100) + 3.5, "text-anchor": "end", class: "tick", "font-size": 10 }, "100");
    txt(f.svg, { x: f.m.l, y: f.H - 2, class: "tick", "font-size": 10 }, quarters[0].slice(2, 4) === "18" ? "’18" : "’" + quarters[0].slice(2, 4));
    txt(f.svg, { x: f.m.l + f.iw, y: f.H - 2, "text-anchor": "end", class: "tick", "font-size": 10 }, "’" + last.k.slice(2, 4));
    const d = "M" + p.idx.map((q, i) => `${x(i).toFixed(1)},${y(q.i).toFixed(1)}`).join("L");
    el("path", { d: `${d}L${x(quarters.length - 1)},${y(0)}L${x(0)},${y(0)}Z`, fill: "var(--fill)" }, f.svg);
    el("path", { d, fill: "none", stroke: color(t), "stroke-width": 2, "stroke-linejoin": "round" }, f.svg);
    const tip = makeTip(host);
    const cross = el("line", { y1: f.m.t, y2: f.m.t + f.ih, stroke: "var(--muted)", "stroke-width": 1, visibility: "hidden" }, f.svg);
    hover(f.svg, f, f.m.l, f.iw, (sx, sy, r) => {
      const i = Math.max(0, Math.min(quarters.length - 1, Math.round((sx - f.m.l) / f.iw * (quarters.length - 1))));
      cross.setAttribute("x1", x(i)); cross.setAttribute("x2", x(i)); cross.setAttribute("visibility", "visible");
      showTip(tip, host, `<div class="t">${label(t)} · ${qLabel(quarters[i])}</div><div class="row">Questions<b>${fmt(p.idx[i].v)}</b></div><div class="row">Index<b>${Math.round(p.idx[i].i)}</b></div>`, x(i) / f.W * r.width, y(p.idx[i].i) / f.H * r.height);
    }, () => { tip.hidden = true; cross.setAttribute("visibility", "hidden"); });
  });
}

/* ---------- share-of-site index ---------- */
function drawShare() {
  const host = document.getElementById("shareidx");
  const f = frame(host, 280, { t: 12, r: 96, b: 22, l: 34 }, "Tag share of all questions, indexed to 2021");
  const mx = Math.ceil(Math.max(...TAGS.flatMap(t => shareIdx[t].map(d => d.i))) / 50) * 50;
  const x = i => f.m.l + (i / (quarters.length - 1)) * f.iw, y = v => f.m.t + f.ih - (v / mx) * f.ih;
  const qe = quarters.indexOf("2022-Q4");
  el("rect", { x: x(qe), y: f.m.t, width: f.m.l + f.iw - x(qe), height: f.ih, fill: "var(--ai-wash)" }, f.svg);
  for (let v = 0; v <= mx; v += 50) { el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: y(v), y2: y(v), class: v === 0 ? "base" : "grid" }, f.svg); txt(f.svg, { x: f.m.l - 6, y: y(v) + 4, "text-anchor": "end", class: "tick" }, String(v)); }
  el("line", { x1: f.m.l, x2: f.m.l + f.iw, y1: y(100), y2: y(100), stroke: "var(--axis)", "stroke-width": 1.5, "stroke-dasharray": "5 4" }, f.svg);
  years.forEach(yr => { const i = quarters.indexOf(`${yr}-Q1`); if (i >= 0 && (f.W > 520 || yr % 2 === 0)) txt(f.svg, { x: x(i), y: f.H - 6, class: "tick" }, f.W > 520 ? String(yr) : "’" + String(yr).slice(2)); });
  const drawOrder = [...TAGS].sort((a, b) => (a === focus) - (b === focus));
  drawOrder.forEach(t => el("path", { d: "M" + shareIdx[t].map((d, i) => `${x(i).toFixed(1)},${y(d.i).toFixed(1)}`).join("L"), fill: "none", stroke: isOff(t) ? "var(--dim)" : color(t), "stroke-width": focus === t ? 3 : 2, "stroke-linejoin": "round" }, f.svg));
  // end labels with simple collision avoidance
  const ends = TAGS.map(t => ({ t, v: shareIdx[t][quarters.length - 1].i, y: y(shareIdx[t][quarters.length - 1].i) })).sort((a, b) => a.y - b.y);
  for (let i = 1; i < ends.length; i++) if (ends[i].y - ends[i - 1].y < 13) ends[i].y = ends[i - 1].y + 13;
  const over = ends[ends.length - 1].y - (f.m.t + f.ih); if (over > 0) ends.forEach(e => (e.y -= over));
  ends.forEach(e => {
    el("circle", { cx: x(quarters.length - 1), cy: y(e.v), r: 3, fill: isOff(e.t) ? "var(--dim)" : color(e.t) }, f.svg);
    txt(f.svg, { x: f.m.l + f.iw + 7, y: e.y + 4, class: "lbl", "font-family": "JetBrains Mono, ui-monospace, monospace", "font-weight": 500, opacity: isOff(e.t) ? 0.4 : 1 }, `${e.t} ${Math.round(e.v)}`);
  });
  const tip = makeTip(host);
  const cross = el("line", { y1: f.m.t, y2: f.m.t + f.ih, stroke: "var(--muted)", "stroke-width": 1, visibility: "hidden" }, f.svg);
  hover(f.svg, f, f.m.l, f.iw, (sx, sy, r) => {
    const i = Math.max(0, Math.min(quarters.length - 1, Math.round((sx - f.m.l) / f.iw * (quarters.length - 1))));
    cross.setAttribute("x1", x(i)); cross.setAttribute("x2", x(i)); cross.setAttribute("visibility", "visible");
    const rows = [...TAGS].sort((a, b) => shareIdx[b][i].i - shareIdx[a][i].i).map(t => `<div class="row"><span><span class="sw" style="background:${color(t)}"></span>${t}</span><b>${Math.round(shareIdx[t][i].i)} · ${shareIdx[t][i].s.toFixed(shareIdx[t][i].s < 1 ? 2 : 1)}%</b></div>`).join("");
    showTip(tip, host, `<div class="t">${qLabel(quarters[i])} · index · share of all questions</div>${rows}`, x(i) / f.W * r.width, sy / f.H * r.height - 4);
  }, () => { tip.hidden = true; cross.setAttribute("visibility", "hidden"); });
}

/* ---------- when each tag fell ---------- */
function drawHalfLife() {
  const host = document.getElementById("halflife");
  const rows = order, rowH = 34, m = { t: 8, r: 10, b: 24, l: 100 };
  const f = frame(host, m.t + rows.length * rowH + m.b, m, "Quarter each tag fell below 50, 25 and 10 percent of its 2021 level");
  const qs = quarters.slice(quarters.indexOf("2022-Q4"));
  const x = q => f.m.l + (qs.indexOf(q) / (qs.length - 1)) * f.iw;
  qs.forEach(q => { if (q.endsWith("Q1")) { el("line", { x1: x(q), x2: x(q), y1: f.m.t, y2: f.m.t + rows.length * rowH, class: "grid" }, f.svg); txt(f.svg, { x: x(q), y: f.H - 6, "text-anchor": "middle", class: "tick" }, q.slice(0, 4)); } });
  const tip = makeTip(host);
  rows.forEach((t, i) => {
    const p = P[t], cy = f.m.t + i * rowH + rowH / 2, off = t !== "site" && isOff(t), c = off ? "var(--dim)" : color(t);
    txt(f.svg, { x: f.m.l - 10, y: cy + 4, "text-anchor": "end", class: "lbl", "font-family": t === "site" ? null : "JetBrains Mono, ui-monospace, monospace", "font-weight": t === "site" ? 600 : 500, opacity: off ? 0.4 : 1 }, t === "site" ? "All questions" : t);
    el("line", { x1: x(p.b50), x2: x(p.b10), y1: cy, y2: cy, stroke: c, "stroke-width": 2, opacity: 0.5 }, f.svg);
    [["b50", 0, "50%"], ["b25", 0.45, "25%"], ["b10", 1, "10%"]].forEach(([key, fo, lab]) => {
      const dot = el("circle", { cx: x(p[key]), cy, r: 6, fill: fo ? c : "var(--card)", "fill-opacity": fo || 1, stroke: c, "stroke-width": 2 }, f.svg);
      const sh = () => { const r = f.svg.getBoundingClientRect(); showTip(tip, host, `<div class="t">${label(t)}</div><div class="row">Below ${lab} of 2021<b>${qLabel(p[key])}</b></div>`, x(p[key]) / f.W * r.width, (cy - 6) / f.H * r.height); };
      dot.addEventListener("pointerenter", sh); dot.addEventListener("pointerdown", sh); dot.addEventListener("pointerleave", () => (tip.hidden = true));
    });
  });
  document.getElementById("hl-legend").innerHTML =
    `<span><svg width="14" height="14" aria-hidden="true"><circle cx="7" cy="7" r="5" fill="none" stroke="currentColor" stroke-width="2"/></svg> below 50%</span>` +
    `<span><svg width="14" height="14" aria-hidden="true"><circle cx="7" cy="7" r="5" fill="currentColor" fill-opacity=".45" stroke="currentColor" stroke-width="2"/></svg> below 25%</span>` +
    `<span><svg width="14" height="14" aria-hidden="true"><circle cx="7" cy="7" r="5" fill="currentColor" stroke="currentColor" stroke-width="2"/></svg> below 10%</span>`;
}
function drawTagCharts() { drawChips(); drawMultis(); drawShare(); drawHalfLife(); }

/* ---------- data table ---------- */
(function () {
  const head = `<tr><th>Quarter</th>${TAGS.map(k => `<th>${k}</th>`).join("")}<th>All questions</th></tr>`;
  const body = quarters.slice().reverse().map(q => `<tr><td>${qLabel(q)}</td>${TAGS.map(k => `<td>${fmt(DATA.tags[k][q])}</td>`).join("")}<td>${fmt(siteQ[q])}</td></tr>`).join("");
  document.getElementById("table").innerHTML = `<table aria-label="Questions per quarter by tag and in total"><thead>${head}</thead><tbody>${body}</tbody></table>`;
})();

/* ---------- views ---------- */
function drawDash() { drawKpis(); drawCliff(); drawAnnual(); drawYoY(); drawHeat(); drawTagCharts(); }
document.getElementById("scale-lin").addEventListener("click", () => setScale(false));
document.getElementById("scale-log").addEventListener("click", () => setScale(true));
drawDash();
/* redraw each chart whenever its own width changes (layout settling, fonts, rotation, window resize) */
const widths = new Map();
const watch = [["kpis", drawKpis], ["cliff", drawCliff], ["annual", drawAnnual], ["yoy", drawYoY], ["heat", drawHeat], ["multis", drawMultis], ["shareidx", drawShare], ["halflife", drawHalfLife]];
if ("ResizeObserver" in window) {
  /* Redraws are batched into the next animation frame, never run inside the observer callback:
     redrawing there changes layout mid-notification and triggers "ResizeObserver loop" errors. */
  const pending = new Set(); let raf = 0;
  const ro = new ResizeObserver(entries => {
    for (const e of entries) {
      const w = Math.round(e.contentRect.width), id = e.target.id;
      if (!w || Math.abs((widths.get(id) || 0) - w) < 2) continue;
      const first = !widths.has(id); widths.set(id, w);
      if (!first) pending.add(id);
    }
    if (pending.size && !raf) raf = requestAnimationFrame(() => {
      raf = 0; const ids = [...pending]; pending.clear();
      ids.forEach(id => watch.find(([k]) => k === id)[1]());
    });
  });
  watch.forEach(([id]) => { const n = document.getElementById(id); widths.set(id, Math.round(n.clientWidth) || undefined); if (!n.clientWidth) widths.delete(id); ro.observe(n); });
} else {
  let rt; addEventListener("resize", () => { clearTimeout(rt); rt = setTimeout(drawDash, 150); });
}
if (document.fonts && document.fonts.ready) document.fonts.ready.then(drawDash);
